css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .42); position: relative; }
.loader .slime { position: absolute; left: 4%; bottom: 8%; height: 10%; width: 0; border-radius: 999px; background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-2) 60%, transparent)); animation: snail-slime calc(var(--loader-speed) * 4) linear infinite; }
.loader .snail { position: absolute; left: 4%; bottom: 8%; width: 30%; height: 74%; animation: snail-crawl calc(var(--loader-speed) * 4) linear infinite; }
.loader .shell { position: absolute; left: 0; top: 4%; width: 66%; height: 76%; border-radius: 50%; background: repeating-conic-gradient(from 0deg at 50% 50%, var(--accent) 0 9%, color-mix(in srgb, #fff 30%, var(--accent)) 0 18%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 18%, transparent); }
.loader .foot { position: absolute; left: 0; bottom: 0; width: 100%; height: 28%; border-radius: 40% 60% 999px 999px; background: var(--accent-2); animation: snail-ripple calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .horn { position: absolute; right: 6%; top: 8%; width: 5%; height: 34%; border-radius: 3px; background: var(--accent-2); transform-origin: 50% 100%; }
.loader .horn:nth-of-type(3) { transform: rotate(-16deg); }
.loader .horn:nth-of-type(4) { right: 18%; transform: rotate(-32deg); }
@keyframes snail-crawl { 0% { transform: translateX(0); } 90%, 100% { transform: translateX(210%); } }
@keyframes snail-slime { 0% { width: 0; opacity: 1; } 90% { width: 88%; opacity: 1; } 98%, 100% { width: 88%; opacity: 0; } }
@keyframes snail-ripple { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(.9) translateX(4%); } }
